A stripped-down mental model of what `malloc`/`free` do, ignoring size classes and alignment for clarity:

```c
typedef struct chunk {
    size_t size;
    int free;
    struct chunk *next;   // free-list link, only meaningful when free
} chunk_t;

void *my_malloc(size_t n) {
    chunk_t *c = free_list_head;
    while (c) {
        if (c->free && c->size >= n) {   // first-fit scan
            c->free = 0;
            return (void *)(c + 1);      // memory right after the header
        }
        c = c->next;
    }
    return request_more_from_os(n);      // sbrk/mmap when nothing fits
}

void my_free(void *ptr) {
    chunk_t *c = (chunk_t *)ptr - 1;      // header sits right before ptr
    c->free = 1;
    coalesce_with_neighbors(c);           // merge adjacent free chunks
}
```

Every pointer `malloc` returns to you is really `header + n` — which is exactly why corrupting the bytes just before your pointer (a classic off-by-one) corrupts the header the next `free()` on that chunk will trust.
